#!/usr/bin/env bash\nset -euo pipefail\n\nSERVICE_NAME="$1"\nREGION="$2"\nPROJECT_ID="$3"\n\nREVISION_URL=$(gcloud run services describe "$SERVICE_NAME" \\n  --region="$REGION" \\n  --project="$PROJECT_ID" \\n  --format='json' \\n  | python3 -c "\nimport sys, json\nsvc = json.load(sys.stdin)\nfor t in svc.get('status', {}).get('traffic', []):\n    if t.get('tag') == 'candidate':\n        print(t.get('url', ''))\n        break\n")\n\nif [ -z "$REVISION_URL" ]; then\n  echo "ERROR: Could not resolve tagged revision URL for 'candidate'."\n  exit 1\nfi\n\necho "Smoke testing: $REVISION_URL/health"\n\nfor i in $(seq 1 12); do\n  STATUS=$(curl -s -o /dev/null -w "%{http_code}" \\n    "$REVISION_URL/health" 2>/dev/null || echo "000")\n  echo "Attempt $i — HTTP $STATUS"\n  if [ "$STATUS" = "200" ]; then\n    echo "Health check passed."\n    exit 0\n  fi\n  sleep 15\ndone\n\necho "Health check failed after all retries — aborting traffic migration."\nexit 1